package mz.bam.seeky.android;
import android.app.*;import android.content.*;import android.graphics.*;import android.net.Uri;import java.io.*;import java.util.*;
final class BookCovers {
    static final int REQUEST=87;
    static void choose(MainActivity a,StudyStore.Row book){a.getSharedPreferences("books",0).edit().putString("pending_cover_hash",book.s("hash")).apply();a.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("image/*"),REQUEST);}
    static void result(MainActivity a,int result,Intent data){if(result!=Activity.RESULT_OK||data==null||data.getData()==null)return;String hash=a.getSharedPreferences("books",0).getString("pending_cover_hash","");if(!hash.matches("[a-f0-9]{64}"))return;Uri uri=data.getData();PlusUi.longRun(a,()->{File temp=File.createTempFile("cover-source-",".image",a.getCacheDir()),target=null;Bitmap image=null;try{temp.delete();try(InputStream in=a.getContentResolver().openInputStream(uri)){if(in==null)throw new IOException("Imagem indisponível.");StudyFiles.copy(in,temp,32L*1048576,()->false);}BitmapFactory.Options size=new BitmapFactory.Options();size.inJustDecodeBounds=true;BitmapFactory.decodeFile(temp.getPath(),size);if(size.outWidth<=0||size.outHeight<=0)throw new IOException("Imagem inválida.");size.inSampleSize=ImageBudget.sample(size.outWidth,size.outHeight,900);size.inJustDecodeBounds=false;image=BitmapFactory.decodeFile(temp.getPath(),size);if(image==null)throw new IOException("Imagem indisponível.");File dir=new File(a.getFilesDir(),"book-covers");dir.mkdirs();target=new File(dir,UUID.randomUUID()+".jpg");try(FileOutputStream out=new FileOutputStream(target)){if(!image.compress(Bitmap.CompressFormat.JPEG,88,out))throw new IOException("Não foi possível guardar a capa.");out.getFD().sync();}final String path=target.getPath();BookSettings.update(a,hash,profile->profile.put("cover",path));try(StudyStore db=new StudyStore(a)){db.getWritableDatabase().update("materials",StudyStore.values("updated",System.currentTimeMillis()),"hash=?",new String[]{hash});}target=null;PlusUi.post(a,()->{a.thumbnails.trim();a.books.reload();});}finally{temp.delete();if(target!=null)target.delete();if(image!=null)image.recycle();}});}
    static File custom(Context c,Catalog.Entry e){try{Uri uri=Uri.parse(e.uri);if(!(c.getPackageName()+".study").equals(uri.getAuthority()))return null;long material=Long.parseLong(uri.getLastPathSegment());try(StudyStore db=new StudyStore(c)){StudyStore.Row book=db.get("materials",material);if(book==null)return null;String path=BookSettings.get(c,book.s("hash")).optString("cover","");if(path.isEmpty())return null;return BackupExtras.privateFile(c,new File(path),"book-covers");}}catch(Exception ignored){return null;}}
    private BookCovers(){}
}
